const $=s=>document.querySelector(s), clamp=THREE.MathUtils.clamp;
const TILE=64, COLS=32, SIZE=TILE*COLS, MAX=128;
let mode='build',tool='add',cameraMode=false,color='#3264ee',brush=8,selected=null,playing=false,playStart=0,showJoints=true;
let mirrors={x:false,y:false,z:false},frameClipboard=null;
let state={nextId:1,boxes:[{id:0,parent:null,p:[0,.5,0],q:[0,0,0,1],anchor:true,slot:0,color:'#f4f7fc',a:null,b:null}],frames:[],frame:0};
normalizeModel(state);
const atlas=document.createElement('canvas');atlas.width=atlas.height=SIZE;
const ctx=atlas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#f4f7fc';ctx.fillRect(0,0,SIZE,SIZE);
const texture=new THREE.CanvasTexture(atlas);texture.colorSpace=THREE.SRGBColorSpace;texture.magFilter=THREE.NearestFilter;texture.minFilter=THREE.LinearFilter;texture.generateMipmaps=false;
const material=new THREE.MeshStandardMaterial({map:texture,roughness:.82,metalness:0});
const viewport=$('#viewport');let renderer;
