renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.setClearColor('#14171d');viewport.appendChild(renderer.domElement);
const canvas=renderer.domElement;canvas.setAttribute('aria-label','3D canvas. Tap a cube face to build. Drag empty space to orbit. Pinch to zoom.');canvas.tabIndex=0;
const scene=new THREE.Scene();scene.fog=new THREE.Fog('#14171d',18,45);
const camera=new THREE.PerspectiveCamera(36,innerWidth/innerHeight,.05,150);const target=new THREE.Vector3(0,.5,0);let radius=Math.max(5.7,4/camera.aspect),theta=.72,phi=1.05;
const hemi=new THREE.HemisphereLight(0xffffff,0x98a9c0,2.4);scene.add(hemi);const light=new THREE.DirectionalLight(0xffffff,2.4);light.position.set(4,7,5);scene.add(light);
const grid=new THREE.GridHelper(100,100,0x363e4c,0x252c36);grid.position.y=-.012;grid.material.transparent=true;grid.material.opacity=.65;scene.add(grid);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(100,100),new THREE.MeshBasicMaterial({color:0x14171d}));floor.rotation.x=-Math.PI/2;floor.position.y=-.02;scene.add(floor);
const group=new THREE.Group();scene.add(group);const meshes=new Map();
const edgeGeometry=new THREE.EdgesGeometry(new THREE.BoxGeometry(1,1,1));const edgeMaterial=new THREE.LineBasicMaterial({color:0x7890ac,transparent:true,opacity:.3});const outline=new THREE.LineSegments(edgeGeometry,new THREE.LineBasicMaterial({color:0x3264ee}));outline.scale.setScalar(1.003);outline.material.depthTest=false;outline.material.transparent=true;outline.material.opacity=.85;outline.renderOrder=10;outline.visible=false;scene.add(outline);
const ghost=new THREE.Mesh(new THREE.BoxGeometry(1.008,1.008,1.008),new THREE.MeshBasicMaterial({color:0x3264ee,opacity:.16,transparent:true,depthWrite:false}));ghost.visible=false;scene.add(ghost);
const jointGroup=new THREE.Group();scene.add(jointGroup);const jointMarkers=new Map(),anchorMarkers=new Map();const jointGeo=new THREE.SphereGeometry(1,12,12),anchorGeo=new THREE.OctahedronGeometry(.075);const jointMaterial=new THREE.MeshBasicMaterial({color:0x3264ee,depthTest:false});const anchorMaterial=new THREE.MeshBasicMaterial({color:0xd0d7e5,depthTest:false});
const cornerGroup=new THREE.Group();scene.add(cornerGroup);const cornerGeo=new THREE.SphereGeometry(1,12,12),cornerMaterial=new THREE.MeshBasicMaterial({color:0xc6d8ff,depthTest:false});const corners=[];for(const x of [-1,1])for(const y of [-1,1])for(const z of [-1,1]){const m=new THREE.Mesh(cornerGeo,cornerMaterial);m.userData.sign=[x,y,z];m.renderOrder=30;cornerGroup.add(m);corners.push(m);}cornerGroup.visible=false;
