let history=[],future=[],transaction=null,toastTimer;
const clone=x=>structuredClone(x);
const vec=a=>new THREE.Vector3().fromArray(a);const quat=a=>new THREE.Quaternion().fromArray(a);
function tileRect(slot,face){const n=slot*6+face;return {x:n%COLS*TILE,y:Math.floor(n/COLS)*TILE};}
function touchTile(slot,face){if(!transaction)return;const key=slot*6+face;if(!transaction.tiles.has(key)){const {x,y}=tileRect(slot,face);transaction.tiles.set(key,ctx.getImageData(x,y,TILE,TILE));}}
function begin(){if(!transaction)transaction={before:clone(state),tiles:new Map()};}
function commit(){if(!transaction)return;const after=clone(state), changed=JSON.stringify(transaction.before)!==JSON.stringify(after)||transaction.tiles.size;if(changed){const tilesAfter=new Map();for(const key of transaction.tiles.keys()){const {x,y}=tileRect(Math.floor(key/6),key%6);tilesAfter.set(key,ctx.getImageData(x,y,TILE,TILE));}history.push({...transaction,after,tilesAfter});if(history.length>40)history.shift();future=[];}transaction=null;renderHistory();}
function historyStep(redo=false){stopPlayback();endDrag();const from=redo?future:history,to=redo?history:future;if(!from.length)return;const item=from.pop();to.push(item);state=normalizeModel(clone(redo?item.after:item.before));closeSheet();for(const [key,data] of (redo?item.tilesAfter:item.tiles)){const {x,y}=tileRect(Math.floor(key/6),key%6);ctx.putImageData(data,x,y);}texture.needsUpdate=true;selected=null;rebuild();renderTools();}
function renderHistory(){$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2300);}
function geometry(slot){const g=new THREE.BoxGeometry(1,1,1),uv=g.attributes.uv;for(let f=0;f<6;f++){const {x,y}=tileRect(slot,f);for(let v=0;v<4;v++){const i=f*4+v;uv.setXY(i,(x+1+uv.getX(i)*(TILE-2))/SIZE,1-(y+1+(1-uv.getY(i))*(TILE-2))/SIZE);}}return g;}
function currentPose(){const p={};for(const [id,m] of meshes)p[id]={p:m.position.toArray(),q:m.quaternion.toArray()};return p;}
function restPose(){return Object.fromEntries(state.boxes.map(b=>[b.id,{p:b.p.slice(),q:b.q.slice()}]));}
function displayPose(pose){for(const b of state.boxes){const p=pose[b.id]||b,m=meshes.get(b.id);m.position.fromArray(p.p);m.quaternion.fromArray(p.q);m.scale.fromArray(dimensions(b));}group.updateMatrixWorld(true);updateSelection();updateJoints();}
function rebuild(){if(mode==='animate'&&!state.frames.length){state.frames=[{time:0,pose:restPose()}];state.frame=0;}for(const m of meshes.values()){m.geometry.dispose();group.remove(m);}meshes.clear();for(const b of state.boxes){const m=new THREE.Mesh(geometry(b.slot),material);m.userData.id=b.id;m.add(new THREE.LineSegments(edgeGeometry,edgeMaterial));group.add(m);meshes.set(b.id,m);}displayPose(mode==='animate'?(state.frames[state.frame]?.pose||restPose()):restPose());makePhysics();renderHistory();}
function updateCamera(){camera.position.setFromSpherical(new THREE.Spherical(radius,phi,theta)).add(target);camera.lookAt(target);camera.updateMatrixWorld();updateSelection();updateJoints();}
function fit(resetAngle=true){const box=new THREE.Box3().setFromObject(group);box.getCenter(target);const size=box.getSize(new THREE.Vector3());const v=Math.tan(THREE.MathUtils.degToRad(camera.fov/2));radius=clamp(Math.max(size.y/v,size.x/(v*camera.aspect),size.z/v)*1.1+1.4,4,65);if(resetAngle){theta=.72;phi=1.05;}updateCamera();}
function keepInView(){group.updateMatrixWorld(true);let outside=false;for(const m of meshes.values())for(const x of [-.5,.5])for(const y of [-.5,.5])for(const z of [-.5,.5]){const p=m.localToWorld(new THREE.Vector3(x,y,z)).project(camera);if(Math.abs(p.x)>.88||p.y>.72||p.y<-.48)outside=true;}if(outside)fit(false);}
function hit(x,y){const r=canvas.getBoundingClientRect();pointer.set((x-r.left)/r.width*2-1,-(y-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);group.updateMatrixWorld(true);return ray.intersectObjects([...meshes.values()],false)[0];}
function placement(h){const parent=state.boxes.find(b=>b.id===h.object.userData.id),n=h.face.normal.clone(),ps=dimensions(parent),local=h.object.worldToLocal(h.point.clone()).multiply(vec(ps));const i=n.toArray().findIndex(v=>Math.abs(v)>.5);for(let k=0;k<3;k++)local.setComponent(k,k===i?n.getComponent(k)*ps[k]/2:clamp(Math.round(local.getComponent(k)*4)/4,-ps[k]/2+.025,ps[k]/2-.025));const pivotB=n.clone().multiplyScalar(-.5),pos=local.clone().sub(pivotB).applyQuaternion(quat(parent.q)).add(vec(parent.p));return {parent,n,pos,a:local.toArray(),b:pivotB.toArray()};}
function candidate(h){return placement(h).pos;}
function addCube(h){if(playing||!h)return;if(state.boxes.length>=MAX)return notify('128 cubes maximum');const at=placement(h),{parent,pos,n}=at;if(state.boxes.some(b=>vec(b.p).distanceTo(pos)<.1))return;begin();const slots=new Set(state.boxes.map(b=>b.slot));let slot=0;while(slots.has(slot))slot++;const b={id:state.nextId++,parent:parent.id,p:pos.toArray(),q:parent.q.slice(),anchor:false,slot,color:'#f4f7fc',a:at.a,b:at.b,size:[1,1,1],normal:n.toArray(),axis:'omni'};state.boxes.push(b);for(let f=0;f<6;f++){touchTile(slot,f);const {x,y}=tileRect(slot,f);ctx.fillStyle=b.color;ctx.fillRect(x,y,TILE,TILE);}for(const frame of state.frames){const pp=frame.pose[parent.id]||parent;frame.pose[b.id]={p:vec(b.a).sub(vec(b.b)).applyQuaternion(quat(pp.q)).add(vec(pp.p)).toArray(),q:pp.q.slice()};}texture.needsUpdate=true;selected=b.id;rebuild();commit();keepInView();}
function eraseCube(id){if(id===0)return notify('Keep the root cube');begin();const removed=new Set([id]);let more=true;while(more){more=false;for(const b of state.boxes)if(removed.has(b.parent)&&!removed.has(b.id)){removed.add(b.id);more=true;}}state.boxes=state.boxes.filter(b=>!removed.has(b.id));for(const f of state.frames)for(const n of removed)delete f.pose[n];selected=null;rebuild();commit();}
function pixelScale(position,pixels){return Math.max(.002,camera.position.distanceTo(position)*2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*pixels/innerHeight);}
function updateSelection(){const m=meshes.get(selected);outline.visible=!!m&&(mode!=='paint');cornerGroup.visible=!!m&&mode==='build'&&tool==='move'&&!cameraMode;if(m){outline.position.copy(m.position);outline.quaternion.copy(m.quaternion);outline.scale.copy(m.scale).multiplyScalar(1.003);if(cornerGroup.visible){for(const c of corners){c.position.copy(vec(c.userData.sign).multiply(m.scale).multiplyScalar(.5).applyQuaternion(m.quaternion).add(m.position));c.scale.setScalar(pixelScale(c.position,5));}}}}
function updateJoints(){const active=new Set(state.boxes.map(b=>b.id));for(const map of [jointMarkers,anchorMarkers])for(const [id,m] of map)if(!active.has(id)){jointGroup.remove(m);map.delete(id);}jointGroup.visible=(mode==='animate'||mode==='build'&&tool==='move')&&showJoints;if(!jointGroup.visible)return;for(const b of state.boxes){const m=meshes.get(b.id);if(b.parent!==null){let j=jointMarkers.get(b.id);if(!j){j=new THREE.Mesh(jointGeo,jointMaterial.clone());j.renderOrder=20;jointGroup.add(j);jointMarkers.set(b.id,j);}j.position.copy(vec(b.b).applyQuaternion(m.quaternion).add(m.position));j.scale.setScalar(pixelScale(j.position,7));j.material.color.set({x:0xf4777e,y:0x82dca4,z:0x80a8ff,omni:0xa1b9ff}[b.axis||'omni']);}let a=anchorMarkers.get(b.id);if(b.anchor&&!a){a=new THREE.Mesh(anchorGeo,anchorMaterial);a.renderOrder=13;jointGroup.add(a);anchorMarkers.set(b.id,a);}if(a){a.visible=b.anchor&&mode==='animate';a.position.copy(m.position);}}}
function makePhysics(){world=new CANNON.World({gravity:new CANNON.Vec3(0,0,0)});world.solver.iterations=60;world.defaultContactMaterial.friction=.05;world.defaultContactMaterial.restitution=0;bodies=new Map();for(const b of state.boxes){const m=meshes.get(b.id),size=dimensions(b);const body=new CANNON.Body({mass:b.anchor?0:Math.max(.1,size[0]*size[1]*size[2]),shape:new CANNON.Box(new CANNON.Vec3(...size.map(n=>n*.495))),linearDamping:.94,angularDamping:.94});body.position.copy(m.position);body.quaternion.copy(m.quaternion);world.addBody(body);bodies.set(b.id,body);}for(const b of state.boxes){if(b.parent===null)continue;let c;if(b.axis&&b.axis!=='omni'){const parent=state.boxes.find(p=>p.id===b.parent),a=axisVector(b.axis),axisB=a.clone().applyQuaternion(quat(parent.q)).applyQuaternion(quat(b.q).invert());c=new CANNON.HingeConstraint(bodies.get(b.parent),bodies.get(b.id),{pivotA:new CANNON.Vec3(...b.a),pivotB:new CANNON.Vec3(...b.b),axisA:new CANNON.Vec3(...a.toArray()),axisB:new CANNON.Vec3(...axisB.toArray()),maxForce:1e5,collideConnected:false});}else{c=new CANNON.PointToPointConstraint(bodies.get(b.parent),new CANNON.Vec3(...b.a),bodies.get(b.id),new CANNON.Vec3(...b.b),1e5);c.collideConnected=false;}world.addConstraint(c);}dragConstraint=null;dragBody=null;}
function screenPoint(p){const q=p.clone().project(camera);return {x:(q.x+1)*innerWidth/2,y:(1-q.y)*innerHeight/2,z:q.z};}
function pickMarker(x,y,entries,radius=19){let best=null,score=Infinity;for(const [id,m] of entries){if(!m.visible)continue;const p=screenPoint(m.position),d=Math.hypot(p.x-x,p.y-y);if(p.z<1&&d<radius&&d<score){best={id,object:m};score=d;}}return best;}
function pickJoint(x,y){return jointGroup.visible?pickMarker(x,y,jointMarkers):null;}
function pickCorner(x,y){return cornerGroup.visible?pickMarker(x,y,corners.map((c,i)=>[i,c]),18):null;}
function beginShape(g){begin();g.base=clone(state);const box=g.base.boxes.find(b=>b.id===selected),parent=g.base.boxes.find(b=>b.id===box.parent);g.box=box;g.original=vec(box.p);g.initialSize=dimensions(box).slice();g.normal=parent?normalFor(box,parent).applyQuaternion(quat(parent.q)):new THREE.Vector3(0,1,0);const point=g.kind==='resize'?g.corner.object.position:g.hit.point;g.plane=new THREE.Plane().setFromNormalAndCoplanarPoint(g.kind==='resize'?camera.getWorldDirection(new THREE.Vector3()):g.normal,point);hit(g.start.x,g.start.y);g.planeStart=ray.ray.intersectPlane(g.plane,new THREE.Vector3());g.sign=g.corner?.object.userData.sign;}
function moveShape(g,x,y){if(!g.base)beginShape(g);if(!g.planeStart)return;hit(x,y);const p=ray.ray.intersectPlane(g.plane,new THREE.Vector3());if(!p)return;const delta=p.sub(g.planeStart);let position=g.original.clone(),size=g.initialSize.slice();if(g.kind==='move'){position.add(delta);}else{const local=delta.clone().applyQuaternion(quat(g.box.q).invert()),normalLocal=g.normal.clone().applyQuaternion(quat(g.box.q).invert()),normalIndex=normalLocal.toArray().findIndex(v=>Math.abs(v)>.5);const shift=new THREE.Vector3();for(let i=0;i<3;i++){const sign=g.sign[i],attached=sign*normalLocal.getComponent(i)<-.5;const next=attached?size[i]:clamp(Math.round((size[i]+sign*local.getComponent(i))*20)/20,.2,12);const change=next-size[i];size[i]=next;shift.setComponent(i,(i===normalIndex?normalLocal.getComponent(i):sign)*change/2);}position.add(shift.applyQuaternion(quat(g.box.q)));}state=editShape(g.base,g.box.id,position.toArray(),size);displayPose(restPose());}
