function startDrag(h){const b=state.boxes.find(b=>b.id===h.object.userData.id);if(b.anchor){notify('Unanchor this cube to move it');return false;}begin();selected=b.id;makePhysics();dragGrab=h.point.clone();dragPlane=new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()),h.point);dragBody=new CANNON.Body({mass:0,type:CANNON.Body.KINEMATIC,collisionFilterGroup:0,collisionFilterMask:0});dragBody.position.copy(h.point);world.addBody(dragBody);const local=bodies.get(b.id).pointToLocalFrame(new CANNON.Vec3(h.point.x,h.point.y,h.point.z));dragConstraint=new CANNON.PointToPointConstraint(bodies.get(b.id),local,dragBody,new CANNON.Vec3(),700);world.addConstraint(dragConstraint);return true;}
function moveDrag(x,y){hit(x,y);const p=ray.ray.intersectPlane(dragPlane,new THREE.Vector3());if(p&&dragBody){const current=new THREE.Vector3(dragBody.position.x,dragBody.position.y,dragBody.position.z);const delta=p.clone().sub(current);if(delta.length()>1)delta.setLength(1);dragBody.position.copy(current.add(delta));}}
function freeze(){if(!world)return;for(const b of bodies.values()){b.velocity.setZero();b.angularVelocity.setZero();b.force.setZero();b.torque.setZero();}}
function endDrag(){if(dragConstraint){world.removeConstraint(dragConstraint);world.removeBody(dragBody);dragConstraint=null;dragBody=null;freeze();displayPose(projectPose(state.boxes,currentPose()));savePose();commit();}settleUntil=0;}
function savePose(){if(mode==='animate'&&state.frames[state.frame])state.frames[state.frame].pose=currentPose();}
function paintHit(h,painted){const b=state.boxes.find(b=>b.id===h.object.userData.id),face=Math.floor(h.faceIndex/2),{x:tx,y:ty}=tileRect(b.slot,face);const px=h.uv.x*SIZE,py=(1-h.uv.y)*SIZE,key=tool==='fill'?`${b.id}:${face}`:`${b.id}:${face}:${Math.round(px)}:${Math.round(py)}`;if(painted.has(key))return;painted.add(key);touchTile(b.slot,face);ctx.save();ctx.beginPath();ctx.rect(tx,ty,TILE,TILE);ctx.clip();ctx.fillStyle=color;if(tool==='fill')ctx.fillRect(tx,ty,TILE,TILE);else{ctx.beginPath();ctx.arc(px,py,brush/2,0,Math.PI*2);ctx.fill();}ctx.restore();texture.needsUpdate=true;}
function paintAt(x,y){const h=hit(x,y);if(!h)return;const painted=new Set();paintHit(h,painted);if(!Object.values(mirrors).some(Boolean))return;const root=state.boxes[0],normal=h.face.normal.clone().applyQuaternion(h.object.quaternion).normalize();for(const sample of mirroredSamples(h.point,normal,vec(root.p),quat(root.q),mirrors).slice(1)){mirrorRay.set(sample.point.clone().addScaledVector(sample.normal,.025),sample.normal.clone().negate());mirrorRay.far=.05;const mirrored=mirrorRay.intersectObjects([...meshes.values()],false)[0];if(mirrored&&mirrored.face.normal.clone().applyQuaternion(mirrored.object.quaternion).dot(sample.normal)>.95)paintHit(mirrored,painted);}}
function stroke(a,b){const d=Math.hypot(b.x-a.x,b.y-a.y),steps=Math.max(1,Math.ceil(d/2));for(let i=1;i<=steps;i++)paintAt(THREE.MathUtils.lerp(a.x,b.x,i/steps),THREE.MathUtils.lerp(a.y,b.y,i/steps));}
function setMode(next){if(!['build','paint','animate'].includes(next))throw Error('Invalid mode');stopPlayback();endDrag();commit();closeSheet();mode=next;tool=mode==='build'?'add':mode==='paint'?'brush':'pose';cameraMode=false;selected=null;ghost.visible=false;if(mode==='animate'&&!state.frames.length){state.frames=[{time:0,pose:restPose()}];state.frame=0;}rebuild();renderTools();}
const toolButton=(id,name,label,active=false)=>`<button id="${id}" class="tool ${active?'active':''}" title="${label}" aria-label="${label}" aria-pressed="${active}">${icon(name)}<span>${label}</span></button>`;
function renderTools(){for(const b of document.querySelectorAll('[data-mode]')){b.innerHTML=icon(b.dataset.mode)+b.dataset.mode[0].toUpperCase()+b.dataset.mode.slice(1);b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);}
$('#orbit').classList.toggle('active',cameraMode);$('#orbit').setAttribute('aria-pressed',cameraMode);
const panel=$('#context-tools');panel.className=mode;
if(mode==='build'){panel.innerHTML=`<button id="move-tool" class="tool move-tool ${tool==='move'?'active':''}" aria-label="Move and resize" aria-pressed="${tool==='move'}" title="Move and resize">${icon('cursor')}</button>`+toolButton('add-tool','add','Cube',tool==='add')+toolButton('erase-tool','erase','Erase',tool==='erase')+'<span class="spacer"></span><button id="project-menu" class="icon-button" aria-label="Project files" title="Project files">'+icon('folder')+'</button>';for(const [id,next] of [['move-tool','move'],['add-tool','add'],['erase-tool','erase']])$('#'+id).onclick=()=>{tool=next;cameraMode=false;ghost.visible=false;closeSheet();renderTools();updateSelection();updateJoints();};$('#project-menu').onclick=projectSheet;}
if(mode==='paint'){panel.innerHTML=`<div class="paint-tools">${toolButton('brush-tool','brush','Brush',tool==='brush')}${toolButton('fill-tool','fill','Fill',tool==='fill')}<span class="spacer"></span><input id="brush-size" aria-label="Brush size" title="Brush size" type="range" min="1" max="30" value="${brush}"><span class="brush-dot" style="--brush:${brush}px"></span></div><div class="palette">${['#f4f7fc','#263342','#3264ee','#e75946','#ffbb4a','#83bf81','#b8a2e6'].map(c=>`<button class="swatch ${c===color?'chosen':''}" style="--swatch:${c}" data-color="${c}" aria-label="Paint ${c}" aria-pressed="${c===color}"></button>`).join('')}<label class="custom-color" title="Choose paint color" style="--swatch:${color}"><input type="color" aria-label="Custom paint color" value="${color}">${icon('add')}</label></div><div class="mirror-tools"><span>${icon('mirror')} Mirror</span>${['x','y','z'].map(a=>`<button data-mirror="${a}" class="axis-button ${mirrors[a]?'active':''}" aria-label="Mirror paint ${a.toUpperCase()}" aria-pressed="${mirrors[a]}">${a.toUpperCase()}</button>`).join('')}</div>`;for(const b of panel.querySelectorAll('[data-mirror]'))b.onclick=()=>{mirrors[b.dataset.mirror]=!mirrors[b.dataset.mirror];renderTools();};$('#brush-tool').onclick=()=>{tool='brush';cameraMode=false;renderTools();};$('#fill-tool').onclick=()=>{tool='fill';cameraMode=false;renderTools();};$('#brush-size').oninput=e=>{brush=+e.target.value;$('.brush-dot').style.setProperty('--brush',brush+'px');};for(const s of panel.querySelectorAll('[data-color]'))s.onclick=()=>{color=s.dataset.color;renderTools();};panel.querySelector('input[type=color]').oninput=e=>{color=e.target.value;for(const s of panel.querySelectorAll('.swatch')){s.classList.toggle('chosen',s.dataset.color===color);s.setAttribute('aria-pressed',s.dataset.color===color);}$('.custom-color').style.setProperty('--swatch',color);};}
if(mode==='animate'){panel.innerHTML=`<div class="timeline"><button id="play" class="play-button" aria-label="${playing?'Pause':'Play'} animation">${icon(playing?'pause':'play')}</button><div class="frames" aria-label="Keyframes">${state.frames.map((f,i)=>`<button data-frame="${i}" class="frame ${i===state.frame?'active':''}" aria-label="Keyframe at ${f.time} seconds" aria-pressed="${i===state.frame}">${icon('key')}<span>${f.time.toFixed(1)}s</span></button>`).join('')}</div><button id="add-frame" class="icon-button" title="Add keyframe" aria-label="Add keyframe">${icon('add')}</button></div><div class="animation-tools"><button id="joints" class="tool ${showJoints?'active':''}" aria-label="Toggle joints" aria-pressed="${showJoints}">${icon('joint')}</button><span class="spacer"></span><label class="time-label"><input id="frame-time" aria-label="Keyframe time in seconds" type="number" min="0" max="60" step="0.1" value="${state.frames[state.frame]?.time||0}" ${state.frame===0?'disabled':''}> s</label><button id="delete-frame" class="icon-button" aria-label="Delete keyframe" ${state.frames.length<2?'disabled':''}>${icon('trash')}</button></div>`;$('#play').onclick=togglePlayback;$('#add-frame').onclick=addFrame;$('#delete-frame').onclick=deleteFrame;$('#joints').onclick=()=>{showJoints=!showJoints;updateJoints();renderTools();};for(const b of panel.querySelectorAll('[data-frame]'))b.onclick=()=>{selectFrame(+b.dataset.frame);keyframeSheet();};$('#frame-time').onchange=e=>{const t=+e.target.value;if(!Number.isFinite(t)||t<=0||t>60||state.frames.some((f,i)=>i!==state.frame&&Math.abs(f.time-t)<.001)){renderTools();return;}stopPlayback();begin();const f=state.frames[state.frame];f.time=t;state.frames.sort((a,b)=>a.time-b.time);state.frame=state.frames.indexOf(f);commit();renderTools();};}
renderHistory();updateSelection();updateJoints();}
function selectFrame(i){stopPlayback();endDrag();state.frame=i;displayPose(state.frames[i].pose);makePhysics();renderTools();}
function addFrame(){stopPlayback();endDrag();if(state.frames.length>=60)return notify('60 keyframes maximum');const time=state.frames.at(-1).time+.5;if(time>60)return notify('60 seconds maximum');begin();state.frames.push({time,pose:currentPose()});state.frame=state.frames.length-1;commit();renderTools();$('.frames')?.scrollTo({left:99999,behavior:'smooth'});}
function deleteFrame(){if(state.frames.length<2)return;stopPlayback();begin();state.frames.splice(state.frame,1);state.frame=Math.max(0,state.frame-1);state.frames[0].time=0;displayPose(state.frames[state.frame].pose);makePhysics();commit();renderTools();}
function togglePlayback(){if(playing){stopPlayback();return;}if(state.frames.length<2)return notify('Add another keyframe to play');endDrag();closeSheet();playing=true;playStart=performance.now();ghost.visible=false;renderTools();}
function stopPlayback(){if(!playing)return;playing=false;if(mode==='animate'&&state.frames[state.frame])displayPose(state.frames[state.frame].pose);makePhysics();renderTools();}
function interpolatePose(a,b,t){const out={};for(const box of state.boxes){const ap=a[box.id]||box,bp=b[box.id]||box;if(box.parent===null){out[box.id]={p:vec(ap.p).lerp(vec(bp.p),t).toArray(),q:quat(ap.q).slerp(quat(bp.q),t).toArray()};}else{const pa=a[box.parent],pb=b[box.parent],parent=out[box.parent],lqa=quat(pa.q).invert().multiply(quat(ap.q)),lqb=quat(pb.q).invert().multiply(quat(bp.q));const parentBox=state.boxes.find(b=>b.id===box.parent);const q=quat(parent.q).multiply(constrainedRelative(box,parentBox,lqa.slerp(lqb,t)));const p=vec(box.a).applyQuaternion(quat(parent.q)).add(vec(parent.p)).sub(vec(box.b).applyQuaternion(q));out[box.id]={p:p.toArray(),q:q.toArray()};}}return out;}
function playTick(now){const end=state.frames.at(-1).time;if(end<=0)return;const t=((now-playStart)/1000)%end;let i=0;while(i<state.frames.length-2&&state.frames[i+1].time<t)i++;const a=state.frames[i],b=state.frames[i+1];displayPose(interpolatePose(a.pose,b.pose,(t-a.time)/(b.time-a.time)));}
function jointSheet(id){selected=id;updateSelection();const b=state.boxes.find(b=>b.id===id);showSheet(`<div class="sheet-row"><span class="sheet-label">Rotation axis</span><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div><div class="axis-options">${['omni','x','y','z'].map(a=>`<button data-axis="${a}" class="axis-button ${b.axis===a?'active':''}" aria-label="Joint axis ${a==='omni'?'Omni':a.toUpperCase()}" aria-pressed="${b.axis===a}">${a==='omni'?'Omni':a.toUpperCase()}</button>`).join('')}</div>`);for(const button of $('#sheet').querySelectorAll('[data-axis]'))button.onclick=()=>{stopPlayback();begin();b.axis=button.dataset.axis;for(const f of state.frames)f.pose=projectPose(state.boxes,f.pose);if(mode==='animate')displayPose(state.frames[state.frame].pose);makePhysics();updateJoints();commit();closeSheet();};}
function keyframeSheet(){showSheet(`<div class="sheet-row"><span class="sheet-label">${state.frames[state.frame].time.toFixed(1)}s</span><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div><div class="frame-actions"><button id="copy-frame" class="sheet-action">${icon('copy')}<span>Copy</span></button><button id="paste-frame" class="sheet-action" ${frameClipboard?'':'disabled'}>${icon('paste')}<span>Paste</span></button></div>`);$('#copy-frame').onclick=()=>{frameClipboard=clone(state.frames[state.frame].pose);closeSheet();notify('Keyframe copied');};$('#paste-frame').onclick=()=>{if(!frameClipboard)return;begin();const f=state.frames[state.frame];f.pose=pastePose(state.boxes,f.pose,frameClipboard);displayPose(f.pose);makePhysics();commit();closeSheet();notify('Keyframe pasted');};}
function anchorSheet(id){selected=id;updateSelection();const b=state.boxes.find(b=>b.id===id);showSheet(`<div class="sheet-row"><button id="anchor-action" class="sheet-action">${icon(b.anchor?'unlock':'anchor')}<span>${b.anchor?'Unanchor':'Anchor'} cube</span></button><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div>`);$('#anchor-action').onclick=()=>{begin();b.anchor=!b.anchor;makePhysics();updateJoints();commit();closeSheet();};}
function showSheet(html){closeSheet();const el=document.createElement('section');el.id='sheet';el.setAttribute('aria-label','Actions');el.innerHTML=html;el.style.bottom=(innerHeight-$('#dock').getBoundingClientRect().top+12)+'px';$('#app').appendChild(el);el.querySelectorAll('.close-sheet').forEach(b=>b.onclick=closeSheet);el.querySelector('button')?.focus();}
function closeSheet(){$('#sheet')?.remove();}
function projectSheet(){showSheet(`<div class="sheet-row"><span class="sheet-label">Project</span><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div><button id="save-project" class="sheet-action">${icon('save')}<span>Save project</span></button><button id="open-project" class="sheet-action">${icon('folder')}<span>Open project</span></button><input type="file" id="project-file" accept=".json,.cube,application/json" hidden>`);$('#save-project').onclick=()=>{downloadProject(state,atlas);closeSheet();};$('#open-project').onclick=()=>$('#project-file').click();$('#project-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const loaded=await readProject(file);begin();for(let slot=0;slot<MAX;slot++)for(let f=0;f<6;f++)touchTile(slot,f);state=normalizeModel(loaded.state);frameClipboard=null;ctx.clearRect(0,0,SIZE,SIZE);ctx.drawImage(loaded.image,0,0);texture.needsUpdate=true;selected=null;rebuild();commit();closeSheet();renderTools();fit();}catch(err){notify(err.message||'Unable to open project');}};}
function exportSheet(){stopPlayback();showSheet(`<div class="sheet-row"><span class="sheet-label">Export</span><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div><button id="download-model" class="sheet-action primary">${icon('download')}<span>Roblox bundle <small>.rbxmx + texture + meshes</small></span></button><p class="export-note">Parts, joints, and keyframes are ready to import. Painted meshes need asset uploads in Roblox Studio.</p><button id="download-project" class="sheet-action">${icon('save')}<span>Editable project <small>.cube</small></span></button>`);$('#download-model').onclick=async()=>{const btn=$('#download-model');btn.disabled=true;try{await downloadBundle(state,atlas,meshes);notify('Roblox bundle exported');closeSheet();}catch(e){notify('Export failed. Try again.');btn.disabled=false;}};$('#download-project').onclick=()=>downloadProject(state,atlas);}
const pointers=new Map();let gesture=null,multi=null;
function cameraPan(dx,dy){const scale=radius*.0015;const right=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,0),up=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,1);target.addScaledVector(right,-dx*scale).addScaledVector(up,dy*scale);updateCamera();}
function multiMetrics(){const [a,b]=[...pointers.values()];return {x:(a.x+b.x)/2,y:(a.y+b.y)/2,d:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y))};}
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(e.button>2)return;canvas.setPointerCapture(e.pointerId);const p={x:e.clientX,y:e.clientY};pointers.set(e.pointerId,p);closeSheet();if(pointers.size>1){if(gesture?.kind==='paint')commit();if(gesture?.base)endShape();endDrag();gesture=null;multi=multiMetrics();return;}const h=hit(p.x,p.y),corner=mode==='build'&&tool==='move'&&!cameraMode?pickCorner(p.x,p.y):null,joint=!cameraMode&&!playing?pickJoint(p.x,p.y):null;let kind=cameraMode||e.button!==0||playing?'camera':corner?'resize':joint?'joint':!h?'camera':mode==='paint'?'paint':mode==='animate'?'pose':tool==='move'?'move':'build';if(kind==='move'){selected=h.object.userData.id;updateSelection();}gesture={start:p,last:p,hit:h,corner,joint,moved:false,kind,pan:e.shiftKey||e.button===2};ghost.visible=false;if(kind==='paint'){begin();paintAt(p.x,p.y);}});
canvas.addEventListener('pointermove',e=>{const p={x:e.clientX,y:e.clientY};if(!pointers.has(e.pointerId)){if(mode==='build'&&tool==='add'&&!cameraMode&&e.pointerType!=='touch'){const h=hit(p.x,p.y);if(h){const c=candidate(h);ghost.visible=!state.boxes.some(b=>vec(b.p).distanceTo(c)<.1);ghost.position.copy(c);ghost.quaternion.copy(h.object.quaternion);}else ghost.visible=false;}return;}pointers.set(e.pointerId,p);if(pointers.size>1){const n=multiMetrics();if(multi){radius=clamp(radius*multi.d/n.d,1.8,80);cameraPan(n.x-multi.x,n.y-multi.y);}multi=n;return;}if(!gesture)return;const g=gesture,dx=p.x-g.last.x,dy=p.y-g.last.y;if(Math.hypot(p.x-g.start.x,p.y-g.start.y)>5)g.moved=true;if(g.kind==='camera'){if(g.pan)cameraPan(dx,dy);else{theta-=dx*.008;phi=clamp(phi-dy*.008,.12,Math.PI-.12);updateCamera();}}else if(g.kind==='paint'){stroke(g.last,p);}else if((g.kind==='move'||g.kind==='resize')&&g.moved){moveShape(g,p.x,p.y);}else if(g.kind==='pose'&&g.moved){if(!g.dragStarted){g.dragStarted=startDrag(g.hit);if(!g.dragStarted)g.kind='blocked';}if(g.dragStarted)moveDrag(p.x,p.y);}else if(g.kind==='build'&&g.moved){g.kind='camera';theta-=dx*.008;phi=clamp(phi-dy*.008,.12,Math.PI-.12);updateCamera();}g.last=p;});
function pointerEnd(e,cancel=false){pointers.delete(e.pointerId);if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(multi){if(pointers.size===0)multi=null;gesture=null;return;}if(!gesture)return;const g=gesture;gesture=null;if(g.kind==='paint')commit();if(g.base)endShape();if(g.dragStarted)endDrag();if(!cancel&&!g.moved){if(g.kind==='build'){if(tool==='add')addCube(g.hit);else eraseCube(g.hit.object.userData.id);}if(g.kind==='pose')anchorSheet(g.hit.object.userData.id);if(g.kind==='joint')jointSheet(g.joint.id);}if(cancel){endDrag();commit();}}
canvas.addEventListener('pointerup',e=>pointerEnd(e));canvas.addEventListener('pointercancel',e=>pointerEnd(e,true));canvas.addEventListener('lostpointercapture',e=>{if(pointers.has(e.pointerId))pointerEnd(e,true);});canvas.addEventListener('pointerleave',()=>ghost.visible=false);
canvas.addEventListener('wheel',e=>{e.preventDefault();radius=clamp(radius*Math.exp(e.deltaY*.001),1.8,80);updateCamera();},{passive:false});
for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>setMode(b.dataset.mode);
for(const [id,name] of [['undo','undo'],['redo','redo'],['orbit','orbit'],['fit','fit']])$('#'+id).innerHTML=icon(name);
$('#export').innerHTML=icon('download')+'Export';$('#undo').onclick=()=>historyStep();$('#redo').onclick=()=>historyStep(true);$('#orbit').onclick=()=>{cameraMode=!cameraMode;ghost.visible=false;renderTools();};$('#fit').onclick=()=>fit();$('#export').onclick=exportSheet;
document.addEventListener('selectstart',e=>e.preventDefault());document.addEventListener('dragstart',e=>e.preventDefault());document.addEventListener('dblclick',e=>e.preventDefault(),{passive:false});
addEventListener('keydown',e=>{if(e.target.matches('input,textarea'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();historyStep(e.shiftKey);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();historyStep(true);}if(e.key==='Escape'){closeSheet();stopPlayback();cameraMode=false;renderTools();}if(e.code==='Space'&&mode==='animate'){e.preventDefault();togglePlayback();}});
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);updateCamera();});
addEventListener('blur',()=>{pointers.clear();if(gesture?.base)endShape();gesture=null;multi=null;endDrag();commit();});
rebuild();renderTools();updateCamera();let last=performance.now();renderer.setAnimationLoop(now=>{const dt=Math.min((now-last)/1000,.05);last=now;if(playing)playTick(now);else if(mode==='animate'&&dragConstraint){world.step(1/120,dt,6);for(const [id,body] of bodies){const m=meshes.get(id);m.position.copy(body.position);m.quaternion.copy(body.quaternion);}updateSelection();updateJoints();}renderer.render(scene,camera);});
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const reg=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};reg({name:'read_cube_model',description:'Read the current cube model and keyframe count.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode,boxes:clone(state.boxes),keyframes:state.frames.map(f=>f.time),poses:clone(state.frames),selected,mirrors:clone(mirrors)})});reg({name:'set_editor_mode',description:'Switch the visible editor mode.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['build','paint','animate']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['build','paint','animate'].includes(input.mode))throw Error('Unknown editor mode');setMode(input.mode);return {mode};}});reg({name:'undo_cube_edit',description:'Undo the last cube, paint, or animation edit.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(!history.length)throw Error('Nothing to undo');historyStep();return {cubes:state.boxes.length,keyframes:state.frames.length};}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
